"""Wi-Fi security policy helpers for PuddleDuck body networking.

The current body-Orin Wi-Fi stack is intentionally restricted to WPA2-Personal.
WPA2/WPA3 transition access points are accepted, but the generated
NetworkManager profile disables Protected Management Frames so SAE/WPA3 cannot
be negotiated. WPA3-only access points are reported as unsupported.
"""

from __future__ import annotations

import re
from typing import Any, Dict

_TOKEN_BOUNDARY = r"(?:^|[^A-Z0-9]){}(?:[^A-Z0-9]|$)"


def _has_token(value: str, token: str) -> bool:
    return re.search(_TOKEN_BOUNDARY.format(re.escape(token)), value) is not None


def classify_advertised_security(value: Any) -> Dict[str, Any]:
    """Classify NetworkManager's human-readable SECURITY field.

    NetworkManager's exact text varies by version. Common examples are
    ``WPA2``, ``WPA3``, ``WPA2 WPA3``, ``SAE`` and ``OWE``. We preserve the raw
    text while returning stable flags for the web UI and connection policy.
    """

    raw = str(value or "").strip()
    normalized = " ".join(raw.upper().replace("_", "-").split())
    is_open = normalized in {"", "--", "NONE", "OPEN"}

    has_wpa2 = _has_token(normalized, "WPA2")
    has_sae = "SAE" in normalized
    has_owe = _has_token(normalized, "OWE")
    has_suite_b = "SUITE-B-192" in normalized or "SUITEB192" in normalized
    has_wpa3 = _has_token(normalized, "WPA3") or has_sae or has_owe or has_suite_b

    transition = bool(has_wpa2 and has_wpa3)
    wpa3_only = bool(has_wpa3 and not has_wpa2)

    if is_open:
        mode = "open"
    elif wpa3_only:
        mode = "wpa3-only"
    elif transition:
        mode = "wpa2-wpa3-transition"
    elif has_wpa2:
        mode = "wpa2"
    else:
        mode = "other"

    if wpa3_only:
        warning = (
            "WPA3-only networks are not supported on this robot. "
            "Enable WPA2 or WPA2/WPA3 transition mode on the access point."
        )
    elif transition:
        warning = "This WPA2/WPA3 network will be joined using WPA2 only."
    else:
        warning = ""

    return {
        "security_mode": mode,
        "wpa3": bool(has_wpa3),
        "wpa3_only": wpa3_only,
        "transition": transition,
        "supported": not wpa3_only,
        "warning": warning,
    }


def is_wpa3_key_mgmt(value: Any) -> bool:
    """Return True for negotiated/selected WPA3 key-management methods."""

    normalized = str(value or "").strip().upper().replace("_", "-")
    if not normalized:
        return False
    return (
        "SAE" in normalized
        or _has_token(normalized, "OWE")
        or "SUITE-B-192" in normalized
        or "SUITEB192" in normalized
    )
